#!/bin/sh
# Generated by gestalt compile: headless worker "research" (worker tier).
# Route: gathering sources for an issue, each with a link and a date
# Usage: sh research.sh "<task, with the user's original request verbatim and decisions since>"
# The worker loads only its own plugins and MCP servers; the lead loads neither.
# Set GESTALT_PLUGIN_PROSE_RESEARCH to the prose-research plugin directory (see SETUP.md).
# Unverified: that --plugin-dir loads a plugin the lead's settings disable. Check once (SETUP.md §5).
set -eu
HERE=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
PROMPT="$(cat "$HERE/research.prompt.md")
${1:?pass the task}"
exec claude -p --model sonnet --strict-mcp-config --plugin-dir "${GESTALT_PLUGIN_PROSE_RESEARCH:?set GESTALT_PLUGIN_PROSE_RESEARCH to the prose-research plugin directory}" "$PROMPT"
